"""Generate native test data from shared JSON and the canonical Python catalog."""

import argparse
import json
from pathlib import Path

from claude_statusline.config import catalog

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "mods/statusline-native/tests/generated-search-fixtures.ts"


def generated():
    cases = json.loads((ROOT / "tests/fixtures/editor-search.json").read_text(encoding="utf-8"))
    return (
        "// Generated by tools/generate_editor_fixtures.py; do not edit.\n"
        + "export const APPEARANCE_CASES = " + (ROOT / "tests/fixtures/appearance.json").read_text(encoding="utf-8").strip() + ";\n"
        + "export const SEARCH_CASES = " + json.dumps(cases, ensure_ascii=False, indent=2) + ";\n"
        + "export const SEARCH_CATALOG = " + json.dumps([item.to_dict() for item in catalog.ITEMS], ensure_ascii=False, indent=2) + ";\n"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    value = generated()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != value:
            parser.exit(1, "Editor fixtures are stale; run tools/generate_editor_fixtures.py\n")
    else:
        OUTPUT.write_text(value, encoding="utf-8")


if __name__ == "__main__":
    main()
